/* Memberships: a product a buyer pays for every month or every year, with posts only its members read. `products.type` takes `membership` (every value it already allows is kept). `membership_plans` is a membership's monthly and yearly price, free trial days, what members get and the products included with it, one row per product; the Stripe price ids on it are the server's. `memberships` is one buyer's subscription as Stripe last said it (active, trialing, past_due, canceled with the period still running, expired), its period end, cancel at period end and card, kept in step by the Stripe webhook; `membership_invoices` is each payment, once per Stripe invoice. `membership_posts` are the creator's updates (text, pictures, files, linked products), `membership_post_reads` which posts a member has opened, `membership_post_emails` one row per member per update so each email goes once. `entitlements.membership_id` marks a library row that a membership granted, so it goes when the membership ends. `membership_grants_access` is the one rule for access (active, trialing, canceled until the period ends, past_due for 7 days) and `membership_access(product)` answers it for the signed in person, by account or by their confirmed email; row level security on posts uses it. Members read their own memberships, invoices and reads; creators read their members and posts; every write is the server's. Needs nothing else. Until it runs, the membership pages say memberships are not set up and nothing else changes. Safe to run again. */
DO $do$ DECLARE def text; BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'memberships: there is no products table, nothing to do.'; RETURN; END IF; SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conname = 'products_type_check' AND conrelid = 'public.products'::regclass; IF def IS NULL OR def LIKE '%''membership''%' THEN RETURN; END IF; ALTER TABLE public.products DROP CONSTRAINT products_type_check; IF def LIKE '%ARRAY[%' THEN EXECUTE 'ALTER TABLE public.products ADD CONSTRAINT products_type_check ' || replace(def, 'ARRAY[', 'ARRAY[''membership''::text, ') || ' NOT VALID'; ELSE ALTER TABLE public.products ADD CONSTRAINT products_type_check CHECK (type IN ('digital', 'course', 'community', 'physical', 'membership')) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.membership_plans (product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, monthly_price_cents integer, yearly_price_cents integer, trial_days integer NOT NULL DEFAULT 0, benefits jsonb NOT NULL DEFAULT '[]'::jsonb, included_product_ids uuid[] NOT NULL DEFAULT '{}', currency text NOT NULL DEFAULT 'usd', stripe_product_id text, stripe_monthly_price_id text, stripe_monthly_price_cents integer, stripe_yearly_price_id text, stripe_yearly_price_cents integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT membership_plans_prices CHECK ((monthly_price_cents IS NULL OR monthly_price_cents BETWEEN 100 AND 1000000) AND (yearly_price_cents IS NULL OR yearly_price_cents BETWEEN 100 AND 10000000)), CONSTRAINT membership_plans_trial CHECK (trial_days BETWEEN 0 AND 90), CONSTRAINT membership_plans_benefits CHECK (jsonb_typeof(benefits) = 'array'));
CREATE INDEX IF NOT EXISTS membership_plans_creator_idx ON public.membership_plans (creator_id);
CREATE TABLE IF NOT EXISTS public.memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, buyer_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, buyer_email text NOT NULL, buyer_name text, title text, stripe_subscription_id text NOT NULL, stripe_customer_id text, stripe_price_id text, billing_interval text NOT NULL DEFAULT 'month', amount_cents integer NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'usd', status text NOT NULL DEFAULT 'incomplete', stripe_status text, trial_end timestamptz, current_period_start timestamptz, current_period_end timestamptz, cancel_at_period_end boolean NOT NULL DEFAULT false, canceled_at timestamptz, ended_at timestamptz, past_due_since timestamptz, started_at timestamptz, card_brand text, card_last4 text, email_updates boolean NOT NULL DEFAULT true, synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT memberships_subscription_once UNIQUE (stripe_subscription_id), CONSTRAINT memberships_status_check CHECK (status IN ('incomplete', 'trialing', 'active', 'past_due', 'canceled', 'expired')), CONSTRAINT memberships_interval_check CHECK (billing_interval IN ('month', 'year')), CONSTRAINT memberships_email_lower CHECK (buyer_email = lower(buyer_email)));
CREATE INDEX IF NOT EXISTS memberships_buyer_idx ON public.memberships (buyer_id) WHERE buyer_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS memberships_email_idx ON public.memberships (buyer_email);
CREATE INDEX IF NOT EXISTS memberships_product_status_idx ON public.memberships (product_id, status);
CREATE INDEX IF NOT EXISTS memberships_creator_idx ON public.memberships (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS memberships_renewing_idx ON public.memberships (current_period_end) WHERE status IN ('active', 'trialing') AND cancel_at_period_end = false;
CREATE TABLE IF NOT EXISTS public.membership_invoices (stripe_invoice_id text PRIMARY KEY, membership_id uuid NOT NULL REFERENCES public.memberships(id) ON DELETE CASCADE, order_id uuid, amount_cents integer NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'usd', status text NOT NULL DEFAULT 'paid', billing_reason text, period_start timestamptz, period_end timestamptz, paid_at timestamptz, hosted_invoice_url text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT membership_invoices_status_check CHECK (status IN ('paid', 'failed', 'open', 'void')));
CREATE INDEX IF NOT EXISTS membership_invoices_membership_idx ON public.membership_invoices (membership_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.membership_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, title text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', images jsonb NOT NULL DEFAULT '[]'::jsonb, attachments jsonb NOT NULL DEFAULT '[]'::jsonb, linked_product_ids uuid[] NOT NULL DEFAULT '{}', published_at timestamptz NOT NULL DEFAULT now(), email_status text NOT NULL DEFAULT 'none', emailed_count integer NOT NULL DEFAULT 0, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT membership_posts_title_len CHECK (char_length(title) <= 200), CONSTRAINT membership_posts_body_len CHECK (char_length(body) <= 20000), CONSTRAINT membership_posts_email_status_check CHECK (email_status IN ('none', 'queued', 'sending', 'sent')), CONSTRAINT membership_posts_shape CHECK (jsonb_typeof(images) = 'array' AND jsonb_typeof(attachments) = 'array'));
CREATE INDEX IF NOT EXISTS membership_posts_feed_idx ON public.membership_posts (product_id, published_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS public.membership_post_reads (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES public.membership_posts(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id));
CREATE INDEX IF NOT EXISTS membership_post_reads_post_idx ON public.membership_post_reads (post_id);
CREATE TABLE IF NOT EXISTS public.membership_post_emails (post_id uuid NOT NULL REFERENCES public.membership_posts(id) ON DELETE CASCADE, membership_id uuid NOT NULL REFERENCES public.memberships(id) ON DELETE CASCADE, email text NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, last_error text, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (post_id, membership_id), CONSTRAINT membership_post_emails_status_check CHECK (status IN ('pending', 'sent', 'skipped', 'failed')));
CREATE INDEX IF NOT EXISTS membership_post_emails_pending_idx ON public.membership_post_emails (created_at) WHERE status = 'pending';
DO $do$ BEGIN IF to_regclass('public.entitlements') IS NULL THEN RAISE NOTICE 'memberships: there is no entitlements table, included products are not granted here.'; RETURN; END IF; ALTER TABLE public.entitlements ADD COLUMN IF NOT EXISTS membership_id uuid REFERENCES public.memberships(id) ON DELETE CASCADE; CREATE INDEX IF NOT EXISTS entitlements_membership_idx ON public.entitlements (membership_id) WHERE membership_id IS NOT NULL; END $do$;
CREATE OR REPLACE FUNCTION public.membership_grants_access(p_status text, p_period_end timestamptz, p_past_due_since timestamptz, p_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path = public AS $f$ SELECT CASE WHEN p_status IN ('active', 'trialing') THEN true WHEN p_status = 'canceled' THEN p_period_end IS NOT NULL AND p_period_end > p_at WHEN p_status = 'past_due' THEN p_past_due_since IS NULL OR p_past_due_since > p_at - interval '7 days' ELSE false END $f$;
CREATE OR REPLACE FUNCTION public.membership_access(p_product_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT auth.uid() IS NOT NULL AND (EXISTS (SELECT 1 FROM public.products p JOIN public.creators c ON c.id = p.creator_id WHERE p.id = p_product_id AND c.user_id = auth.uid()) OR EXISTS (SELECT 1 FROM public.memberships m WHERE m.product_id = p_product_id AND public.membership_grants_access(m.status, m.current_period_end, m.past_due_since, now()) AND (m.buyer_id = auth.uid() OR m.buyer_email = (SELECT lower(u.email::text) FROM auth.users u WHERE u.id = auth.uid() AND u.email_confirmed_at IS NOT NULL)))) $f$;
REVOKE ALL ON FUNCTION public.membership_access(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.membership_access(uuid) TO authenticated, service_role;
ALTER TABLE public.membership_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_post_reads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_post_emails ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.membership_plans, public.memberships, public.membership_invoices, public.membership_posts, public.membership_post_reads, public.membership_post_emails FROM anon, authenticated;
GRANT SELECT (product_id, creator_id, monthly_price_cents, yearly_price_cents, trial_days, benefits, included_product_ids, currency, updated_at) ON public.membership_plans TO anon, authenticated;
GRANT SELECT ON public.memberships, public.membership_invoices, public.membership_posts, public.membership_post_reads TO authenticated;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib plan of a published membership" ON public.membership_plans; CREATE POLICY "storelib plan of a published membership" ON public.membership_plans FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id = membership_plans.product_id AND p.status = 'published')); DROP POLICY IF EXISTS "storelib creator reads own plan" ON public.membership_plans; CREATE POLICY "storelib creator reads own plan" ON public.membership_plans FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = membership_plans.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib member reads own membership" ON public.memberships; CREATE POLICY "storelib member reads own membership" ON public.memberships FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid())); DROP POLICY IF EXISTS "storelib creator reads members" ON public.memberships; CREATE POLICY "storelib creator reads members" ON public.memberships FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = memberships.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib member or creator reads invoices" ON public.membership_invoices; CREATE POLICY "storelib member or creator reads invoices" ON public.membership_invoices FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.memberships m WHERE m.id = membership_invoices.membership_id AND (m.buyer_id = (SELECT auth.uid()) OR EXISTS (SELECT 1 FROM public.creators c WHERE c.id = m.creator_id AND c.user_id = (SELECT auth.uid()))))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read posts" ON public.membership_posts; CREATE POLICY "storelib members read posts" ON public.membership_posts FOR SELECT TO authenticated USING (deleted_at IS NULL AND public.membership_access(product_id)); DROP POLICY IF EXISTS "storelib creator reads own posts" ON public.membership_posts; CREATE POLICY "storelib creator reads own posts" ON public.membership_posts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = membership_posts.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib member reads own post reads" ON public.membership_post_reads; CREATE POLICY "storelib member reads own post reads" ON public.membership_post_reads FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid())); END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_keep_deleted_row()') IS NULL THEN RETURN; END IF; DROP TRIGGER IF EXISTS memberships_keep_deleted ON public.memberships; CREATE TRIGGER memberships_keep_deleted BEFORE DELETE ON public.memberships FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS membership_posts_keep_deleted ON public.membership_posts; CREATE TRIGGER membership_posts_keep_deleted BEFORE DELETE ON public.membership_posts FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS membership_plans_keep_deleted ON public.membership_plans; CREATE TRIGGER membership_plans_keep_deleted BEFORE DELETE ON public.membership_plans FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); END $do$;
notify pgrst, 'reload schema';
